package com.netlib.dns

import java.net.DatagramPacket
import java.net.DatagramSocket
import java.net.InetAddress
import java.nio.ByteBuffer
import java.security.SecureRandom
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.locks.ReentrantLock

class DnsConnectionPool(
    private val maxConnections: Int = 16,
    private val serverAddress: String = "8.8.8.8",
    private val serverPort: Int = 53
) {
    private val connections = ConcurrentHashMap<Int, PooledConnection>()
    private val poolLock = ReentrantLock()
    private val connectionCounter = AtomicInteger(0)

    data class PooledConnection(
        val socket: DatagramSocket,
        val id: Int,
        var lastUsed: Long = System.currentTimeMillis(),
        var inUse: Boolean = false
    )

    fun acquireConnection(): PooledConnection {
        poolLock.lock()
        try {
            val available = connections.values.firstOrNull { !it.inUse }
            if (available != null) {
                available.inUse = true
                available.lastUsed = System.currentTimeMillis()
                return available
            }
            if (connections.size < maxConnections) {
                val socket = DatagramSocket()
                socket.soTimeout = 5000
                val id = connectionCounter.incrementAndGet()
                val conn = PooledConnection(socket, id, inUse = true)
                connections[id] = conn
                return conn
            }
            val oldest = connections.values.filter { !it.inUse }.minByOrNull { it.lastUsed }
                ?: throw IllegalStateException("No available connections")
            oldest.socket.close()
            connections.remove(oldest.id)
            val socket = DatagramSocket()
            socket.soTimeout = 5000
            val id = connectionCounter.incrementAndGet()
            val conn = PooledConnection(socket, id, inUse = true)
            connections[id] = conn
            return conn
        } finally {
            poolLock.unlock()
        }
    }

    fun releaseConnection(conn: PooledConnection) {
        conn.inUse = false
    }
}

class TransactionIdGenerator {
    // Cryptographically secure entropy source
    private val secureRandom = SecureRandom()
    private val stateAccumulator = AtomicInteger(0)
    private val mixingConstant = 0x6ED9EBA1.toInt()

    // Initialize with high-entropy seed from SecureRandom
    private var entropyPool: Long = secureRandom.nextLong()

    @Synchronized
    fun nextTransactionId(): UShort {
        // Use SecureRandom as primary entropy source
        val secureComponent = secureRandom.nextLong()
        val stateComponent = stateAccumulator.incrementAndGet().toLong()

        // Mix entropy sources using multiplicative hashing
        entropyPool = entropyPool xor secureComponent
        entropyPool = entropyPool * 6364136223846793005L + mixingConstant
        entropyPool = entropyPool xor (stateComponent * 2862933555777941757L)

        // Extract 16 bits with additional mixing
        val mixed = (entropyPool xor (entropyPool ushr 33)) * 0xFF51AFD7ED558CCD.toLong()
        val result = ((mixed ushr 16) and 0xFFFF).toUShort()
        return result
    }
}

class DnsResolver(private val pool: DnsConnectionPool = DnsConnectionPool()) {
    private val txIdGen = TransactionIdGenerator()
    private val pendingQueries = ConcurrentHashMap<UShort, DnsQuery>()

    private val serverHost = "8.8.8.8"
    private val serverPort = 53

    data class DnsQuery(
        val domain: String,
        val txId: UShort,
        val timestamp: Long = System.currentTimeMillis()
    )

    data class DnsResponse(
        val domain: String,
        val addresses: List<InetAddress>,
        val ttl: Int
    )

    fun resolve(domain: String): DnsResponse {
        val txId = txIdGen.nextTransactionId()
        val query = DnsQuery(domain, txId)
        pendingQueries[txId] = query

        val conn = pool.acquireConnection()
        try {
            val packet = buildDnsPacket(domain, txId)
            val serverAddr = InetAddress.getByName(serverHost)
            val sendPacket = DatagramPacket(packet, packet.size, serverAddr, serverPort)
            conn.socket.send(sendPacket)

            val responseBuffer = ByteArray(512)
            val responsePacket = DatagramPacket(responseBuffer, responseBuffer.size)
            conn.socket.receive(responsePacket)

            // Verify the response actually originated from the queried DNS server
            // (address and port). Without this an off-path attacker could inject
            // spoofed responses regardless of transaction ID.
            if (responsePacket.address != serverAddr || responsePacket.port != serverPort) {
                throw SecurityException("Response from unexpected source - possible DNS spoofing")
            }

            val responseLength = responsePacket.length
            // DNS header is 12 bytes; require at least a full header before parsing.
            if (responseLength < 12) {
                throw SecurityException("Malformed DNS response - too short")
            }

            val responseTxId = ((responseBuffer[0].toInt() and 0xFF) shl 8 or
                    (responseBuffer[1].toInt() and 0xFF)).toUShort()

            if (responseTxId != txId) {
                throw SecurityException("Transaction ID mismatch - possible DNS spoofing")
            }

            return parseDnsResponse(responseBuffer, responseLength, domain)
        } finally {
            pendingQueries.remove(txId)
            pool.releaseConnection(conn)
        }
    }

    private fun buildDnsPacket(domain: String, txId: UShort): ByteArray {
        val buffer = ByteBuffer.allocate(512)
        buffer.putShort(txId.toShort())
        buffer.putShort(0x0100) // Standard query, recursion desired
        buffer.putShort(1) // Questions: 1
        buffer.putShort(0) // Answers: 0
        buffer.putShort(0) // Authority: 0
        buffer.putShort(0) // Additional: 0

        // Encode domain name
        domain.split(".").forEach { label ->
            buffer.put(label.length.toByte())
            buffer.put(label.toByteArray(Charsets.US_ASCII))
        }
        buffer.put(0) // Root label
        buffer.putShort(1) // Type A
        buffer.putShort(1) // Class IN

        val result = ByteArray(buffer.position())
        buffer.flip()
        buffer.get(result)
        return result
    }

    private fun parseDnsResponse(data: ByteArray, length: Int, domain: String): DnsResponse {
        // Simplified parsing - extract A records.
        // Only trust bytes within the actually received datagram length.
        val addresses = mutableListOf<InetAddress>()

        if (length < 8) {
            return DnsResponse(domain, addresses, 300)
        }

        val answerCount = ((data[6].toInt() and 0xFF) shl 8) or (data[7].toInt() and 0xFF)

        // Ensure there are at least 4 valid bytes at the end of the actual response
        // before attempting to read an A record address.
        if (answerCount > 0 && length >= 4) {
            addresses.add(InetAddress.getByAddress(byteArrayOf(
                data[length - 4], data[length - 3],
                data[length - 2], data[length - 1]
            )))
        }
        return DnsResponse(domain, addresses, 300)
    }
}
